/**
 * Builds the checkout request the storefront POSTs to the backend
 * (cart/<cartCode>/checkout), mirroring the request built in
 * src/pages/other/Checkout.js.
 *
 * Body field names follow the backend's order request: shippingQuote
 * (chosen shipping option), currency, isAgree (terms accepted), message
 * (order comment) and the payment object.
 */
export function buildCheckoutRequest({
  cartCode,
  shippingOptionId,
  currency,
  paymentToken,
  paymentModule,
  amount,
  agreedToTerms,
  comments
} = {}) {
  const path = "'`cart/${cartCode}/checkout`;

  const body = {
    shippingQuote: shippingOptionId,
    currency: currency,
    isAgree: agreedToTerms,
    message: comments,
    payment: {
      paymentType: "CREDITCARD",
      transactionType: "CAPTURE",
      paymentModule: paymentModule,
      paymentToken: paymentToken,
      amount: amount
    }
  };

  return {
    method: "POST",
    path: path,
    body: body
  };
}
EOF
